From 127e8c87bb0dc55c65dff8e11f79399b0866d129 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:15:02 +0100
Subject: [PATCH] applets/taskmanager: scroll tasks instead of shrinking them
 to nothing

When the panel was crowded, tasks kept shrinking with no lower limit and
their icons became too small to use. Tasks now keep at least their full
icon size, and the task list scrolls with the wheel when it overflows.

BUG: 447603
---
 applets/taskmanager/qml/MouseHandler.qml |  8 ++---
 applets/taskmanager/qml/Task.qml         |  3 ++
 applets/taskmanager/qml/main.qml         | 37 +++++++++++++++++++++---
 3 files changed, 39 insertions(+), 9 deletions(-)

diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..a18396144c 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -37,15 +37,13 @@ DropArea {
             return;
         }

-        // RtL horizontal TaskLists do not include the spacer (which are initial in this
-        // configuration), if any, but the mouse event coordinates do. We need to subtract
-        // them, or we end thinking we're dragging way right of where we actually are.
-        const rtlSpacerAdjustment = target.LayoutMirroring.enabled ? tasks.width - target.width : 0;
         let above;
         if (isGroupDialog) {
             above = target.itemAt(event.x, event.y);
         } else {
-            above = target.childAt(event.x - rtlSpacerAdjustment, event.y);
+            // The TaskList can be offset by RtL spacers and by scrolling.
+            const pos = mapToItem(target, event.x, event.y);
+            above = target.childAt(pos.x, pos.y);
         }

         if (!above) {
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..f871d8462f 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -46,6 +46,9 @@ PlasmaCore.ToolTipArea {
         ? -1
         : ((model.IsLauncher && !tasksRoot.iconsOnly) ? tasksRoot.height / taskList.rows : TaskManagerApplet.LayoutMetrics.preferredMaxWidth())
     Layout.maximumHeight: tasksRoot.vertical ? TaskManagerApplet.LayoutMetrics.preferredMaxHeight() : -1
+    Layout.minimumWidth: tasksRoot.vertical || inPopup
+        ? -1
+        : Math.min(Layout.maximumWidth, TaskManagerApplet.LayoutMetrics.preferredMinLauncherWidth())

     required property var model
     required property int index
diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..630eae53af 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -460,8 +460,27 @@ PlasmoidItem {
                 top: parent.top
             }

-            height: taskList.height
-            width: taskList.width
+            height: Math.min(taskList.height, tasks.height)
+            width: Math.min(taskList.width, tasks.width)
+            clip: overflow > 0
+
+            // When the tasks don't fit even at their minimum size, scroll them
+            // instead of shrinking them further.
+            readonly property real overflow: tasks.vertical ? taskList.height - tasks.height : taskList.width - tasks.width
+            property real scrollPosition: 0
+            readonly property real scrollOffset: Math.max(0, Math.min(scrollPosition, overflow))
+
+            WheelHandler {
+                acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+                enabled: tmf.overflow > 0
+                onWheel: event => {
+                    let delta = event.pixelDelta.y || event.pixelDelta.x;
+                    if (delta === 0) {
+                        delta = (event.angleDelta.y || event.angleDelta.x) / 120 * TaskManagerApplet.LayoutMetrics.preferredMinLauncherWidth();
+                    }
+                    tmf.scrollPosition = Math.max(0, Math.min(tmf.scrollOffset - delta, tmf.overflow));
+                }
+            }

             TaskList {
                 id: taskList
@@ -470,6 +489,8 @@ PlasmoidItem {
                 anchors {
                     left: parent.left
                     top: parent.top
+                    leftMargin: tasks.vertical ? 0 : -tmf.scrollOffset
+                    topMargin: tasks.vertical ? -tmf.scrollOffset : 0
                 }

                 count: tasksModel.count
@@ -495,6 +516,14 @@ PlasmoidItem {
                         }, 0);
                     return Math.round(totalMaxHeight / heightOccupation);
                 }
+                readonly property real contentMinimumWidth: {
+                    const totalMinWidth = children.reduce((accumulator, child) => accumulator + child.Layout.minimumWidth, 0);
+                    return Math.ceil(totalMinWidth / widthOccupation) || 0;
+                }
+                readonly property real contentMinimumHeight: {
+                    const totalMinHeight = children.reduce((accumulator, child) => accumulator + child.Layout.minimumHeight, 0);
+                    return Math.ceil(totalMinHeight / heightOccupation) || 0;
+                }
                 width: {
                     if (tasks.shouldShrinkToZero) {
                         return 0;
@@ -502,7 +531,7 @@ PlasmoidItem {
                     if (tasks.vertical) {
                         return tasks.width * Math.min(1, widthOccupation);
                     } else {
-                        return Math.min(tasks.width, Layout.maximumWidth);
+                        return Math.max(Math.min(tasks.width, Layout.maximumWidth), contentMinimumWidth);
                     }
                 }
                 height: {
@@ -510,7 +539,7 @@ PlasmoidItem {
                         return 0;
                     }
                     if (tasks.vertical) {
-                        return Math.min(tasks.height, Layout.maximumHeight);
+                        return Math.max(Math.min(tasks.height, Layout.maximumHeight), contentMinimumHeight);
                     } else {
                         return tasks.height * Math.min(1, heightOccupation);
                     }
-- 
2.53.0
